const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderOutcomeForm(task,{selectedOutcome='',activeMinutes=0}={}){
  const partial=selectedOutcome==='partial',completed=selectedOutcome==='completed';
  const minutes=Math.round(activeMinutes),timeText=activeMinutes<=0?'No focus time recorded for this attempt.':activeMinutes<1?'Less than a minute of focus recorded.':minutes+' active '+(minutes===1?'minute':'minutes')+' recorded.';
  return `<form id="outcome-form"><p class="eyebrow">SAVE YOUR ATTEMPT</p><h2>How did it go?</h2><p class="muted">${esc(task.resource+' '+task.section+' · '+task.heading)}</p><div class="outcome-grid">${[['completed','✓','Completed','I met the milestone'],['partial','◔','Partial','There is more to work on'],['ensam','⌘','ENSAM priority','Coursework came first'],['skipped','↷','Skipped','Not available today']].map(([value,icon,title,help])=>`<label><input type="radio" name="outcome" value="${value}" ${selectedOutcome===value?'checked':''} required><span>${icon}</span><b>${title}</b><small>${help}</small></label>`).join('')}</div><section id="completion-evidence" class="completion-evidence" ${completed?'':'hidden'}><span class="detail-label">The milestone you’re confirming</span><p>${esc(task.evidence)}</p></section><label id="partial-estimate" ${partial?'':'hidden'}>Remaining minutes, if partial (estimate)<input name="remaining" type="number" step="any" min="1" max="10000" placeholder="Optional — revise the estimate if needed" ${partial?'':'disabled'}></label><label>What did you demonstrate or leave unfinished?<textarea name="note" placeholder="A result, a blocker, or the next step…" rows="3" maxlength="2000"></textarea></label><p class="small muted">${timeText} Completion stays your decision.</p><div class="dialog-actions"><button type="button" class="text-button" data-close>Back</button><button class="primary">Save session</button></div></form>`;
}
